INSERT INTO courses(id,title,summary,description,subject,level,instructor,price,objectives,extra,published,updated_at)
VALUES('foundations','مدخل إلى العلوم الطبية','كورس تجريبي لبداية منظّمة في رحلتك الطبية. يستطيع المشرف تعديل محتواه وبياناته من لوحة التحكم.','هذا كورس تجريبي لإعداد منصة BayMed. يمكن للمشرف استبدال هذا الوصف وإضافة الدروس والمراجع والأهداف التعليمية قبل استقبال الطلاب. لا يحتوي الكورس حاليًا على مادة طبية تعليمية منشورة.','العلوم الطبية الأساسية','المرحلة الجامعية','',0,'["تعرّف إلى تنظيم المحتوى التعليمي على المنصة","استخدم الملاحظات الشخصية أثناء الدراسة"]','بيانات تجريبية قابلة للتعديل؛ السعر المعروض تجريبي، وتفعيل الوصول يتم يدويًا.',1,unixepoch());
